export function findSellers(categories, query='', sort='rating') {
 const needle = query.toLocaleLowerCase('id-ID');
 return ROWS.filter(r=>categories.includes(r.category) && r.rating>=4.9 && r.reviews>=500 && (r.name+' '+r.city).toLocaleLowerCase('id-ID').includes(needle))
 .sort((a,b)=>(sort==='reviews'? b.reviews-a.reviews : b.rating-a.rating) || a.id-b.id);
}
